\draw[thick] (O) -- (A) node[midway, below] {$9\text{ cm}$};
\draw[thick] (O) -- (B) node[midway, above left] {$9\text{ cm}$};
\draw[thick, blue] (A) arc (0:120:3);
\pic[draw, "$\frac{2\pi}{3}$", angle radius=0.8cm, angle eccentricity=1.5] {angle=A--O--B};
\node[left] at (O) {$O$};
